update public.cozinha_preparacoes set rendimento_final_g=9771, observacao='Base original TD15 com quantidades em gramas. Calabresa e paio proporcionais à gramatura da ficha. Rendimento teórico com fatores atuais cadastrados: feijão 3x; calabresa -10%; bacon -35%; costela suína -30%; cebola -23%; alho -10%. Água de hidratação contada uma vez. Pesar lote final e unidades de embutidos para calibrar.' where nome='Feijoada';
